-- Disposable development project only; all synthetic fixtures are rolled back.
begin;
select set_config('test.writer',gen_random_uuid()::text,true),set_config('test.editor',gen_random_uuid()::text,true),set_config('test.regular',gen_random_uuid()::text,true);
insert into auth.users(id) select current_setting(k)::uuid from unnest(array['test.writer','test.editor','test.regular']) as k;
insert into public.admin_profiles(user_id,role) values (current_setting('test.writer')::uuid,'writer'),(current_setting('test.editor')::uuid,'editor');
insert into public.official_sources(name,organization,url,verified_on,review_due,is_verified) values ('test-source','test','https://example.invalid/source',(now() at time zone 'Asia/Riyadh')::date - 1,(now() at time zone 'Asia/Riyadh')::date + 1,true);
insert into public.date_events(slug,title,program,event_date,date_status,publication_status,source_id,verified_on,review_due) select 'test-event','test','test',(now() at time zone 'Asia/Riyadh')::date + 30,'official','published',id,(now() at time zone 'Asia/Riyadh')::date,(now() at time zone 'Asia/Riyadh')::date + 1 from public.official_sources where name='test-source';
set local role anon;
do $$ begin if (select count(*) from public.date_events where slug='test-event') <> 1 then raise exception 'verified event invisible'; end if; end $$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.writer'),true);
set local role authenticated;
do $$ begin begin insert into public.date_events(slug,title,program) values ('test-writer','test','test'); raise exception 'writer insert allowed'; exception when insufficient_privilege then null; end; end $$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.regular'),true);
set local role authenticated;
do $$ begin if (select count(*) from public.event_revisions) <> 0 then raise exception 'revision leak'; end if; end $$;
reset role;
select set_config('request.jwt.claim.sub',current_setting('test.editor'),true);
set local role authenticated;
do $$ begin update public.date_events set title='updated' where slug='test-event'; if not found then raise exception 'editor update denied'; end if; if (select count(*) from public.event_revisions where snapshot->>'slug'='test-event') <> 2 then raise exception 'event revisions missing'; end if; begin update public.date_events set date_status='estimated' where slug='test-event'; raise exception 'estimated publication allowed'; exception when check_violation then null; end; update public.official_sources set is_verified=false where name='test-source'; end $$;
reset role;
set local role anon;
do $$ begin if (select count(*) from public.date_events where slug='test-event') <> 0 then raise exception 'unverified source visible'; end if; end $$;
reset role;
update public.official_sources set is_verified=true,verified_on=(now() at time zone 'Asia/Riyadh')::date - 5,review_due=(now() at time zone 'Asia/Riyadh')::date - 1 where name='test-source';
set local role anon;
do $$ begin if (select count(*) from public.date_events where slug='test-event') <> 0 then raise exception 'expired source visible'; end if; end $$;
reset role;
select 'event RLS smoke tests passed; fixtures rolled back' as result;
rollback;
